#!/usr/bin/env node
/**
 * Merges the automation/scheduler dataset (source: Claude Desktop outputs
 * AUTOMA~1.JSO / AUTOMA~2.JSO) into storage/automation-sessions.json — the
 * automation-only session log, kept separate from storage/repair-sessions.json
 * (see RepairLogger.js). This script only writes the raw session log; the
 * training JSONL files are derived artifacts regenerated by
 * scripts/export-training-data.mjs, not written directly here.
 *
 * This is additive only:
 *  - domain 'automation' and its subdomain slugs were added to
 *    knowledge/subdomains.js (label formatting only — not wired into
 *    IntentClassifier.js's routing keyword list on its own; that's done
 *    separately).
 *  - repairSessions.schema.json gained 'automation' in the domain enum plus
 *    the extra fields these records carry (intent, parameters, riskLevel,
 *    verification, rollback, ...) as optional properties, and is reused to
 *    validate automation-sessions.json too.
 *
 * Raw subdomain labels in the source ("Task Scheduler", "startup",
 * "Event Viewer") are free text, same problem fix-subdomains.mjs solved for
 * the repair data — mapped here via each record's `intent` field instead,
 * since intent is already a clean machine key.
 *
 * Usage: node scripts/merge-automation-data.mjs [--dry-run]
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkDuplicates } from './dataset-manager.mjs';
import { classifyCommand } from '../src/agent/dangerClassifier.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SESSIONS = path.join(root, 'storage', 'automation-sessions.json');
const dryRun = process.argv.includes('--dry-run');

const SRC_SESSIONS = 'C:/Users/Admin/AppData/Local/Packages/CLAUDE~1/LOCALC~1/Roaming/Claude/LOCAL-~1/2C8610~1/F4BC96~1/LOCAL_~1/outputs/AUTOMA~1.JSO';
const SRC_DATASET = 'C:/Users/Admin/AppData/Local/Packages/CLAUDE~1/LOCALC~1/Roaming/Claude/LOCAL-~1/2C8610~1/F4BC96~1/LOCAL_~1/outputs/AUTOMA~2.JSO';

const INTENT_TO_SUBDOMAIN = {
  'schedule.backup.folder': 'backup',
  'schedule.sync.files': 'sync',
  'schedule.script.powershell': 'script',
  'schedule.app.launch': 'startup',
  'schedule.cleanup': 'cleanup',
  'schedule.service.control': 'service',
  'task.create': 'scheduler',
  'task.delete': 'scheduler',
  'startup.manage': 'startup',
  'schedule.reminder': 'reminder',
  'schedule.diagnostic': 'diagnostic',
  'schedule.eventlog.collect': 'eventlog',
  'monitor.diskspace': 'diskmonitor',
  'monitor.folder': 'foldermonitor',
  'schedule.shutdown': 'power',
  'schedule.maintenance': 'maintenance',
  'files.find.large': 'filesearch',
  'files.find.duplicates': 'filesearch',
  'files.find.old': 'filesearch',
  'files.organize': 'fileorganize',
  'files.rename.bulk': 'fileorganize',
  'files.compress': 'filecompress',
  'files.recover.deleted': 'filerecovery',
  'files.recyclebin.empty': 'cleanup',
  'backup.before.update': 'backup',
  'backup.verify': 'backup',
  'backup.restore.version': 'backup',
  'backup.monitor.storage': 'backup',
  'app.uninstall': 'appmanage',
  'app.find.storage': 'appmanage',
  'app.find.unused': 'appmanage',
  'app.kill.frozen': 'appmanage',
  'app.cache.clear': 'cleanup',
  'cleanup.updatecache': 'cleanup',
  'cleanup.storage.report': 'diagnostic',
  'photos.organize.bydate': 'fileorganize',
  'photos.find.duplicates': 'filesearch',
  'photos.move.drive': 'fileorganize',
  'photos.find.largevideos': 'filesearch',
  'work.diagnostics.collect': 'diagnostic',
  'work.healthreport': 'diagnostic',
  'work.find.recent': 'filesearch',
  'work.archive.projects': 'fileorganize',
  'backup.disk.to.disk': 'backup',
  'backup.before.uninstall': 'backup',
  'backup.browser.data': 'backup',
  'backup.failure.detect': 'backup',
  'backup.restore.files': 'backup',
  'backup.config.files': 'backup',
  'app.version.check': 'appmanage',
  'app.outdated.detect': 'appmanage',
  'app.install': 'appmanage',
  'app.repair': 'appmanage',
  'app.running.check': 'appmanage',
  'app.reset': 'appmanage',
  'cleanup.browser.cache': 'cleanup',
  'cleanup.logs': 'cleanup',
  'cleanup.desktop': 'cleanup',
  'photos.find.all': 'filesearch',
  'photos.compress': 'filecompress',
  'photos.find.duplicate.videos': 'filesearch',
  'work.morning.check': 'diagnostic',
  'work.daily.folder': 'fileorganize',
  'work.tempfiles.clean': 'cleanup',
  'work.project.backup': 'backup',
};

// ── load + verify source ──────────────────────────────────────────────────
const sourceSessions = JSON.parse(fs.readFileSync(SRC_SESSIONS, 'utf8'));
const sourceDatasetLines = fs.readFileSync(SRC_DATASET, 'utf8').split('\n').filter((l) => l.trim());
const sourceDataset = sourceDatasetLines.map((l) => JSON.parse(l));

if (sourceSessions.length !== sourceDataset.length) {
  console.error(`Source mismatch: ${sourceSessions.length} sessions vs ${sourceDataset.length} dataset lines. Aborting.`);
  process.exit(1);
}

const unmappedIntent = sourceSessions.filter((s) => !INTENT_TO_SUBDOMAIN[s.intent]);
if (unmappedIntent.length) {
  console.error('Unmapped intent(s) — add to INTENT_TO_SUBDOMAIN before merging:');
  unmappedIntent.forEach((s) => console.error(`  ${s.intent} (goal: ${s.goal})`));
  process.exit(1);
}

// Refuse to import a step recorded as executed that the live classifier would
// block — same guard as add-entries-batch.mjs, so this script can't
// reintroduce the poisoned-training-data bug fixed earlier. Confirmation-gate
// placeholder steps ("<awaiting confirmation...>", blocked:true) are exempt:
// they're not real commands, and a command appearing again right after with
// blocked:false is the legitimate "confirmed, then executed" pattern this
// dataset uses throughout.
const dangerousUnconfirmed = [];
for (const s of sourceSessions) {
  for (const step of s.steps) {
    if (step.blocked || !step.command || step.command.startsWith('<')) continue;
    if (classifyCommand(step.command).level === 'blocked') {
      const hasConfirmGate = s.steps.some((st) => st.blocked && st.command?.startsWith('<'));
      if (!hasConfirmGate) dangerousUnconfirmed.push({ goal: s.goal, command: step.command });
    }
  }
}
if (dangerousUnconfirmed.length) {
  console.error('Refusing to merge: dangerous command with no confirmation gate in its session:');
  dangerousUnconfirmed.forEach((d) => console.error(`  ${d.goal} -> ${d.command}`));
  process.exit(1);
}

// ── build repair-sessions.json records ─────────────────────────────────────
const sessionRecords = sourceSessions.map((s) => ({
  id: s.id,
  createdAt: s.createdAt,
  goal: s.goal,
  domain: 'automation',
  subdomain: INTENT_TO_SUBDOMAIN[s.intent],
  plan: [], // source has no separate diagnostic plan; plannedAction covers it
  steps: s.steps.map((st) => ({
    command: st.command,
    blocked: st.blocked,
    exitCode: st.exitCode,
    stdout: st.stdout || '',
    stderr: st.stderr || '',
    reason: st.reason,
  })),
  resolved: Boolean(s.resolved),
  summary: s.summary || '',
  recommendation: s.recommendation || '',
  feedback: s.feedback || null,
  type: 'automation',
  intent: s.intent,
  parameters: s.parameters || {},
  missingParameters: s.missingParameters || [],
  clarification: s.clarification ?? null,
  riskLevel: s.riskLevel,
  requiresConfirmation: Boolean(s.requiresConfirmation),
  plannedAction: s.plannedAction || '',
  verification: s.verification || [],
  rollback: s.rollback ?? null,
}));

if (dryRun) {
  console.log(`--dry-run: would rebuild automation-sessions.json with ${sessionRecords.length} sessions from source.`);
  console.log('Subdomain mapping:');
  sourceSessions.forEach((s) => console.log(`  ${s.intent.padEnd(28)} -> ${INTENT_TO_SUBDOMAIN[s.intent]}`));
  process.exit(0);
}

// Rebuild (overwrite), not incremental add: the source file at SRC_SESSIONS
// is the single growing dataset, and it has been overwritten with new/raw
// batches mid-session before — an incremental addEntries() dedup by id would
// just skip re-cleaning records whose id it already knows about, silently
// leaving stale/raw copies in place instead of the freshly mapped version.
// User-added feedback would be lost by this if it ever gets attached to an
// automation session — none has been yet (addFeedback matches this file too).
fs.mkdirSync(path.dirname(SESSIONS), { recursive: true });
fs.writeFileSync(SESSIONS, JSON.stringify(sessionRecords, null, 2) + '\n', 'utf8');
console.log(`automation-sessions.json  rebuilt from source: ${sessionRecords.length} sessions`);

const dupSessions = checkDuplicates(SESSIONS, { key: 'id' });
console.log(`\nPost-write duplicate check: sessions=${dupSessions.duplicateCount}`);
console.log('Run `node scripts/export-training-data.mjs` to regenerate the JSONL training files from the updated session logs.');
